def native_case_verdict(case, report, top, mutation):
    assert case in EXPECTED, 'Unknown fixture case'
    expected = EXPECTED[case]
    finals = re.findall(r'^Final result:\s*(.*?)\s*$', report, re.M)
    assert len(finals) == 1, 'Missing/ambiguous native verdict'
    assert finals[0] == expected['final'], 'Case-specific finite native verdict changed'
    observed = {key:top.get(key,[]) for key in ['devices','nets','pins','badnets','badelements']}
    assert mutation == expected['mutation'], 'Declared source fault differs from qualified fixture'
    evidence = observed == expected['top']
    return {'completed':True,'match_uniquely':finals[0]=='Circuits match uniquely.',
        'native_final_result':finals[0],'targeted_native_evidence_verified':evidence,
        'targeted_evidence_mechanism':'Exact case-specific active hierarchy, per-side typed contact graph, pin correspondence and source fault observed in fixture06',
        'native_top_pin_differences':[(a,b) for a,b in zip(*top['pins']) if a!=b],
        'native_badnet_groups':len(top.get('badnets',[])), 'independent_semantic_review_required':True}
